#include <stdio.h>
#include <stdlib.h>

int main(void) {
    size_t n = 5;
    int *a = malloc(n * sizeof *a);   // sizeof *a stays right if the type changes
    if (a == NULL) {
        fprintf(stderr, "out of memory\n");
        return 1;
    }
    for (size_t i = 0; i < n; i++)
        a[i] = (int)(i + 1);
    for (size_t i = 0; i < n; i++)
        printf("%d ", a[i]);          // 1 2 3 4 5
    free(a);
    a = NULL;                         // a now cannot be misused by accident
    return 0;
}

